# app/tasks/routes.py
from flask import Blueprint, jsonify, request

from app.tasks import service

bp = Blueprint("tasks", __name__, url_prefix="/api/v1")


@bp.get("/tasks")
def list_tasks():
    items = service.list_tasks()
    return jsonify({"items": items, "total": len(items)})


@bp.post("/tasks")
def create_task():
    data = request.get_json(silent=True)
    if data is None:
        return jsonify({"error": {"status": 400, "message": "ожидали JSON"}}), 400
    task, error = service.create_task(data)
    if error is not None:
        return jsonify(error), 422
    return jsonify(task), 201


@bp.delete("/tasks/<int:task_id>")
def delete_task(task_id):
    if service.delete_task(task_id):
        return "", 204
    return jsonify({"error": {"status": 404, "message": "задача не найдена"}}), 404

